# Replaces the image's main config. Serves the built SPA and proxies /api/ to the API replicas.
# Directive reference: https://nginx.org/en/docs/dirindex.html

# Pinned, because "auto" starts one worker per CPU and each worker keeps its own idle upstream connections.
worker_processes 2;
# Room for both workers' connections, two per proxied request, whatever limit the host sets.
worker_rlimit_nofile 8192;
# The unprivileged image can write only to /tmp.
pid /tmp/nginx.pid;
error_log /dev/stderr warn;

# Each proxied request holds two connections: one to the browser, one to the API.
events {
    worker_connections 4096;
}

http {
    include mime.types;
    access_log /dev/stdout;

    client_body_temp_path /tmp/client_temp;
    proxy_temp_path /tmp/proxy_temp;
    fastcgi_temp_path /tmp/fastcgi_temp;
    uwsgi_temp_path /tmp/uwsgi_temp;
    scgi_temp_path /tmp/scgi_temp;

    gzip on;
    gzip_types text/css application/javascript text/javascript application/json;

    # Docker's embedded DNS. A short validity picks up replicas whose addresses change.
    resolver 127.0.0.11 valid=10s ipv6=off;

    # Pass on the caller's request id, or make one, so nginx and the API log the same id.
    map $http_x_request_id $req_id {
        default $http_x_request_id;
        "" $request_id;
    }

    # Swagger UI at /api/docs loads its script and stylesheet from jsDelivr, its icon from fastapi.tiangolo.com,
    # and starts from one inline script allowed by its hash; the hash changes when FastAPI changes that script.
    map $uri $csp {
        default "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
        /api/docs "default-src 'self'; script-src 'self' https://cdn.jsdelivr.net 'sha256-eV3QMumkWxytVHa/LDvu+mnW+PcSAEI4SfFu0iIlbDc='; style-src 'self' https://cdn.jsdelivr.net; img-src 'self' data: https://fastapi.tiangolo.com; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
    }

    upstream api {
        # "resolve" re-reads the replicas' addresses from DNS; it needs a shared zone.
        # https://nginx.org/en/docs/http/ngx_http_upstream_module.html#resolve
        zone api 64k;
        server api:8000 resolve;
        # At most 16 idle connections per worker, 32 in all, well under each replica's 200-connection limit.
        # https://nginx.org/en/docs/http/ngx_http_upstream_module.html#keepalive
        keepalive 16;
        # Shorter than uvicorn's 75 s, so nginx never reuses a connection the API is closing.
        keepalive_timeout 60s;
    }

    server {
        listen 8080;
        root /usr/share/nginx/html;
        server_tokens off;
        client_max_body_size 64k;

        # Every response carries these; a location's own headers are added to them, not swapped for them.
        # https://nginx.org/en/docs/http/ngx_http_headers_module.html#add_header_inherit
        add_header_inherit merge;
        add_header Content-Security-Policy $csp always;
        add_header X-Content-Type-Options nosniff always;
        add_header Referrer-Policy strict-origin-when-cross-origin always;
        add_header X-Frame-Options DENY always;
        add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
        add_header Cross-Origin-Opener-Policy same-origin always;

        # The health probes are for Docker and Kubernetes only, never the public front door.
        location = /livez {
            return 404;
        }
        location = /readyz {
            return 404;
        }

        # Since nginx 1.29.7 the proxy speaks HTTP/1.1 and sends no Connection header by default,
        # which upstream keep-alive needs. https://nginx.org/en/CHANGES-1.30
        location /api/ {
            proxy_pass http://api;
            proxy_set_header Host $host;
            proxy_set_header X-Request-ID $req_id;
            proxy_read_timeout 30s;
        }

        # Vite puts a content hash in every asset's name, so a file never changes under its URL.
        # Cache-Control has no "always", so a missing asset's 404 is never cached for a year.
        location /assets/ {
            add_header Cache-Control "public, max-age=31536000, immutable";
        }

        # Any other path is a client-side route: serve index.html, and have the browser revalidate it every time.
        location / {
            try_files $uri /index.html;
            add_header Cache-Control "no-cache";
        }
    }
}
